# maturity_logistic ----
## IO correctness ----
test_that("`maturity_logistic_create()` returns a backend handle", {
    #' @description Test that `maturity_logistic_create()` returns an integer handle.
    expect_type(
        object = maturity_logistic_create(10, 0.2),
        type = "integer"
    )
})

test_that("`maturity_logistic()` matches the logistic maturity formula", {
    #' @description Test that `maturity_logistic()` evaluates the same values as the underlying logistic formula.
    expect_equal(
        object = maturity_logistic(c(9, 10, 11), 10, 0.2),
        expected = c(
            1 / (1 + exp(-0.2 * (9 - 10))),
            0.5,
            1 / (1 + exp(-0.2 * (11 - 10)))
        )
    )
})

## Error handling ----
test_that("`maturity_logistic()` rejects mismatched parameter lengths", {
    #' @description Test that `maturity_logistic()` errors when `slope` does not have length 1 or the same length as `inflection_point`.
    expect_error(
        object = maturity_logistic(c(9, 10, 11), c(10, 11, 12), c(0.2, 0.3)),
        regexp = "must have length 1 or match the length of the paired input"
    )
})

test_that("`maturity_logistic_create()` registers fixed and random effects", {
    #' @description Test that maturity create calls register fixed and random effects when estimation types are provided.
    clear()

    before <- native_information_parameter_counts()

    maturity_logistic_create(
        inflection_point = 10,
        slope = 0.2,
        inflection_point_estimation_type = "fixed_effects",
        slope_estimation_type = "random_effects"
    )

    after <- native_information_parameter_counts()

    expect_equal(
        object = after[["fixed_effects_parameters"]] - before[["fixed_effects_parameters"]],
        expected = 1L
    )
    expect_equal(
        object = after[["random_effects_parameters"]] - before[["random_effects_parameters"]],
        expected = 1L
    )
})
